import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total, itemCount } from '../src/cart.js';

test('total without discount', () => {
  assert.equal(total([{ price: 100, qty: 2 }, { price: 50, qty: 1 }]), 250);
});

// n lines, each one unit at `price`.
const lines = (n, price) => Array.from({ length: n }, () => ({ price, qty: 1 }));

// Issue #12: rate 0 must keep working as before.
test('rate 0: 10 lines get the 5% bulk discount once', () => {
  assert.equal(total(lines(10, 1000)), 9500);
  assert.equal(total(lines(10, 1000), 0), 9500);
});

test('rate 0: 9 lines get no bulk discount', () => {
  assert.equal(total(lines(9, 1000)), 9000);
});

// Issue #12: the customer discount is applied exactly once.
test('rate 0.1 on a 1,000 cart under 10 lines is 900', () => {
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900);
});

// 10,000 -> 9,000 after the customer discount -> 8,550 after 5% bulk.
test('rate 0.1 on 10 lines: customer discount, then 5% bulk once', () => {
  assert.equal(total(lines(10, 1000), 0.1), 8550);
});

// 9,000 -> 8,100 after the customer discount; no bulk under 10 lines.
test('rate 0.1 on 9 lines: customer discount only', () => {
  assert.equal(total(lines(9, 1000), 0.1), 8100);
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});
